package global

import("context";"fmt";"net";"strings";"time")
type ResolverProbe struct{Name string;Address string;Network string}
type Result struct{Name string;Address string;Reachable bool;Latency time.Duration;Error string}
func Probe(ctx context.Context,p ResolverProbe,timeout time.Duration)Result{p.Name=strings.TrimSpace(p.Name);p.Address=strings.TrimSpace(p.Address);result:=Result{Name:p.Name,Address:p.Address};if p.Address==""||len(p.Address)>2048{return Result{Name:p.Name,Address:p.Address,Error:"resolver address is invalid"}};if len(p.Name)>256{result.Error="resolver name too long";return result};if p.Network==""{p.Network="tcp"};if p.Network!="tcp"&&p.Network!="udp"{result.Error=fmt.Sprintf("unsupported network: %s",p.Network);return result};if timeout<=0{timeout=5*time.Second};if timeout>30*time.Second{timeout=30*time.Second};if ctx==nil{result.Error="context is required";return result};if err:=ctx.Err();err!=nil{result.Error=err.Error();return result};start:=time.Now();dialer:=net.Dialer{Timeout:timeout};conn,err:=dialer.DialContext(ctx,p.Network,p.Address);result.Latency=time.Since(start);if err!=nil{result.Error=fmt.Sprintf("probe failed: %v",err);return result};if err:=conn.Close();err!=nil{result.Error=fmt.Sprintf("probe close failed: %v",err);return result};result.Reachable=true;return result}
func RankByLatency(results []Result)[]Result{out:=append([]Result(nil),results...);for i:=1;i<len(out);i++{for j:=i;j>0;j--{left,right:=out[j-1],out[j];if betterOrEqual(left,right){break};out[j-1],out[j]=out[j],out[j-1]}};return out}
func betterOrEqual(a,b Result)bool{if a.Reachable!=b.Reachable{return a.Reachable};if !a.Reachable{return true};return a.Latency<=b.Latency}
